//! Embeds the icon (`assets/agentdeck.ico`) and the version data in the Windows executable.
//! The `.ico` is generated by `scripts/gerar-icone.ps1` from the logo drawing (`icons.rs`).

fn main() {
    println!("cargo:rerun-if-changed=assets/agentdeck.ico");
    println!("cargo:rerun-if-changed=build.rs");
    if std::env::var("CARGO_CFG_TARGET_OS").is_ok_and(|os| os == "windows") {
        let mut res = winresource::WindowsResource::new();
        res.set_icon("assets/agentdeck.ico");
        res.set("ProductName", "AgentDeck");
        res.set("FileDescription", "AgentDeck");
        if let Err(e) = res.compile() {
            // Without the resource compiler (rc.exe) the app still builds, just without the icon in the .exe.
            println!("cargo:warning=could not embed the icon in the executable: {e}");
        }
    }
}
